problems.answer:
public class Solution {
    public static int[] solve(int[][] matrix) {
        int[] sums = new int[matrix.length];
        for (int row = 0; row < matrix.length; row++) {
            for (int value : matrix[row]) {
                sums[row] += value;
            }
        }
        return sums;
    }
}

