problems.answer:
import java.util.*;

public class Solution {
    public static Map<Character, Integer> solve(String text) {
        Map<Character, Integer> counts = new LinkedHashMap<>();
        for (char letter : text.toCharArray()) {
            counts.merge(letter, 1, Integer::sum);
        }
        return counts;
    }
}

